-- 药品库（训练中心 · 药房）：结构化药品数据，仅供内科教学参考
-- 1) 药品主表 drug：科室(多值) × 药理分类 双维，移动端按维筛选
-- 2) 内置精选内科常见药种子（约 110 种，覆盖内科教研演示场景）
-- 注：字段内容仅为教学演示摘要，用药一律以最新版说明书与医嘱为准（移动端详情页固定展示免责声明）

CREATE TABLE IF NOT EXISTS drug (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '药品ID',
    generic_name VARCHAR(100) NOT NULL COMMENT '通用名（必填，主展示名）',
    trade_name VARCHAR(120) DEFAULT NULL COMMENT '商品名/别名',
    english_name VARCHAR(160) DEFAULT NULL COMMENT '英文名',
    category VARCHAR(60) NOT NULL COMMENT '药理分类（如 β受体阻滞剂 / PPI / 双胍类）',
    department VARCHAR(120) NOT NULL COMMENT '科室标签，多值逗号分隔（如 心血管内科,神经内科）',
    dosage_form VARCHAR(120) DEFAULT NULL COMMENT '剂型规格（如 肠溶片 100mg×30片）',
    indications TEXT COMMENT '适应症',
    usage_dosage TEXT COMMENT '用法用量（教学摘要，以说明书为准）',
    adverse_reactions TEXT COMMENT '不良反应',
    contraindications TEXT COMMENT '禁忌',
    precautions TEXT COMMENT '注意事项',
    is_otc TINYINT NOT NULL DEFAULT 0 COMMENT '是否非处方药：0处方 1非处方',
    status TINYINT NOT NULL DEFAULT 1 COMMENT '1上架 0下架',
    sort INT NOT NULL DEFAULT 0 COMMENT '排序权重，越大越靠前',
    created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    PRIMARY KEY (id),
    KEY idx_category (category),
    KEY idx_department (department),
    KEY idx_generic_name (generic_name),
    KEY idx_status_sort (status, sort)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='药品库（内科教学用药参考）';

