INSERT INTO drug (generic_name, trade_name, english_name, category, department, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, is_otc, sort) VALUES
('阿司匹林肠溶片', '拜阿司匹灵', 'Aspirin Enteric-coated Tablets', '抗血小板药', '心血管内科,神经内科', '肠溶片 100mg×30片', '抗血小板聚集，用于动脉粥样硬化性心脑血管疾病的一、二级预防，如冠心病、缺血性脑卒中。', '口服，一日1次，一次100mg，餐前或餐后整片吞服（具体遵医嘱）。', '胃肠道不适、恶心、出血风险增加；长期使用可致消化道溃疡。', '活动性消化性溃疡、出血体质、对阿司匹林过敏者禁用。', '手术前需评估停药时间；与华法林等抗凝药联用出血风险增高；哮喘患者慎用。', 0, 100),
('硫酸氢氯吡格雷片', '波立维', 'Clopidogrel Bisulfate Tablets', '抗血小板药', '心血管内科,神经内科', '片剂 75mg×7片', '与阿司匹林联用于急性冠脉综合征、支架植入术后；亦用于缺血性卒中/外周动脉疾病。', '口服，一日1次，一次75mg；负荷剂量遵医嘱。', '出血（瘀斑、鼻衄、消化道出血等）、腹泻、皮疹。', '活动性病理性出血（如消化性溃疡出血、颅内出血）者禁用。', '与质子泵抑制剂合用可降低活性代谢物暴露，注意相互作用评估；手术前停用遵医嘱。', 0, 95),
('华法林钠片', NULL, 'Warfarin Sodium Tablets', '抗凝药（维生素K拮抗剂）', '心血管内科', '片剂 3mg×100片', '预防和治疗血栓栓塞性疾病，如房颤卒中预防、深静脉血栓、肺栓塞、心脏瓣膜置换术后。', '口服，剂量个体化，依据INR调整，常用维持量一日2.5～5mg。', '出血（牙龈、皮下瘀斑、血尿等）；偶见皮肤坏死。', '严重肝肾功能不全、活动性出血、妊娠期（尤其早孕期）禁用。', '需定期监测INR并据此调量；避免与阿司匹林、NSAIDs、部分抗菌药物等影响凝血的药物联用。', 0, 92),
('利伐沙班片', '拜瑞妥', 'Rivaroxaban Tablets', '抗凝药（直接Xa因子抑制剂）', '心血管内科', '片剂 10mg/15mg/20mg', '非瓣膜性房颤患者的卒中与体循环栓塞预防；DVT/PE的治疗与复发预防；髋膝关节置换术后VTE预防。', '口服，房颤卒中预防常用一日1次20mg（与餐同服），具体遵医嘱。', '出血、贫血、恶心；肝功能异常偶见。', '活动性大出血、伴凝血异常的肝病、妊娠及哺乳期禁用。', '肾功能不全需按肌酐清除率调整剂量；与强效CYP3A4/P-gp抑制剂联用需谨慎。', 0, 90),
('苯磺酸氨氯地平片', '络活喜', 'Amlodipine Besylate Tablets', '钙通道阻滞剂（CCB）', '心血管内科', '片剂 5mg×7片', '高血压、慢性稳定性心绞痛及变异型心绞痛。', '口服，一日1次，一次5～10mg，最大剂量一日10mg。', '踝部水肿、头痛、面部潮红、心悸、乏力。', '对二氢吡啶类过敏者、严重低血压者禁用。', '肝功能不全者需减量起始；停药应逐步减量，避免骤然停药反跳。', 0, 88),
('硝苯地平控释片', '拜新同', 'Nifedipine Controlled-release Tablets', '钙通道阻滞剂（CCB）', '心血管内科', '控释片 30mg×7片', '高血压、慢性稳定性心绞痛（劳累性心绞痛）。', '口服，一日1次，一次30mg，整片吞服不可掰开。', '头痛、面部潮红、踝部水肿、牙龈增生。', '心源性休克、严重主动脉瓣狭窄患者禁用；妊娠20周内避免使用。', '控释骨架片不可掰开或嚼碎；与葡萄柚汁同服可影响血药浓度。', 0, 85),
('琥珀酸美托洛尔缓释片', '倍他乐克', 'Metoprolol Succinate Extended-release Tablets', 'β受体阻滞剂', '心血管内科', '缓释片 47.5mg×7片', '高血压、心绞痛、慢性心力衰竭（稳定期）、心律失常及心肌梗死后二级预防。', '口服，一日1次，47.5～95mg起始（心衰需从低剂量逐步滴定），具体遵医嘱。', '心动过缓、乏力、头晕、四肢发冷；心衰患者低血压。', '严重心动过缓、二/三度房室传导阻滞、心源性休克、失代偿性心衰禁用。', '不可骤然停药以免心绞痛加重或反跳；哮喘/慢阻肺患者慎用并需β2激动剂支持。', 0, 84),
('富马酸比索洛尔片', '康忻', 'Bisoprolol Fumarate Tablets', 'β受体阻滞剂', '心血管内科', '片剂 5mg×10片', '高血压、冠心病（心绞痛）、慢性稳定性心力衰竭。', '口服，一日1次，一次2.5～10mg，心衰从低剂量开始滴定。', '心动过缓、低血压、头晕、乏力。', '急性心衰或心衰失代偿期、严重心动过缓、房室传导阻滞、病态窦房结综合征禁用。', '慢性阻塞性肺病/哮喘患者慎用；停药需逐渐减量。', 0, 83),
('缬沙坦胶囊', '代文', 'Valsartan Capsules', '血管紧张素Ⅱ受体拮抗剂（ARB）', '心血管内科', '胶囊 80mg×7粒', '高血压、慢性心力衰竭、心肌梗死后左室功能不全。', '口服，一日1次，一次80～160mg。', '头晕、低血压、高钾血症、一过性肾功能影响。', '妊娠期、双侧肾动脉狭窄、高钾血症患者禁用。', '与保钾利尿剂/补钾剂联用注意高钾；开始治疗及加量时监测肾功能与血钾。', 0, 80),
('氯沙坦钾片', '科素亚', 'Losartan Potassium Tablets', '血管紧张素Ⅱ受体拮抗剂（ARB）', '心血管内科', '片剂 50mg×7片', '高血压；对伴蛋白尿的2型糖尿病肾病患者可延缓肾病进展。', '口服，一日1次，一次50mg，可增至100mg。', '头晕、乏力、高钾血症；偶见一过性肝酶升高。', '妊娠期、高钾血症、双侧肾动脉狭窄者禁用。', '血容量不足者（如利尿剂大量使用）首剂可能低血压，需调整。', 0, 79),
('卡托普利片', NULL, 'Captopril Tablets', '血管紧张素转换酶抑制剂（ACEI）', '心血管内科', '片剂 25mg×100片', '高血压、心力衰竭、心肌梗死后心功能不全、糖尿病肾病。', '口服，一日2～3次，一次12.5～25mg，餐前1小时服用为宜。', '持续性干咳、低血压、高钾血症、皮疹；罕见血管神经性水肿。', '妊娠期、双侧肾动脉狭窄、有血管神经性水肿史者禁用。', '注意监测血钾与肾功能；首剂低血压风险患者从小剂量开始。', 0, 78),
('氢氯噻嗪片', NULL, 'Hydrochlorothiazide Tablets', '噻嗪类利尿剂', '心血管内科,肾内科', '片剂 25mg×100片', '水肿性疾病（心源性/肾性水肿）、原发性高血压、尿崩症辅助。', '口服，一日1～2次，一次25～50mg（降压常一日12.5～25mg）。', '低钾血症、低钠血症、高尿酸血症、血糖血脂代谢影响。', '对磺胺类过敏者、无尿患者、严重电解质紊乱者禁用。', '长期使用需补钾或联用保钾药物并定期查电解质、尿酸；痛风患者慎用。', 0, 75),
('呋塞米片', NULL, 'Furosemide Tablets', '袢利尿剂', '心血管内科,肾内科', '片剂 20mg×100片', '心衰水肿、肝硬化腹水、肾病综合征及高血压急症辅助利尿。', '口服，起始一日20～40mg，按利尿效果调整，具体遵医嘱。', '水电解质紊乱（低钾低钠）、脱水、耳鸣（大剂量）、高尿酸。', '严重电解质紊乱、肝昏迷前期、无尿患者禁用。', '强效利尿需监测体重、血压、电解质；与氨基糖苷类联用增加耳毒性风险。', 0, 73),
('螺内酯片', NULL, 'Spironolactone Tablets', '醛固酮拮抗剂（保钾利尿）', '心血管内科,肾内科', '片剂 20mg×100片', '水肿性疾病、原发性醛固酮增多症；与ACEI/ARB/β阻滞剂联用于慢性心衰。', '口服，一日1～2次，一次20～40mg。', '高钾血症、男性乳房发育、月经紊乱、胃肠道反应。', '高钾血症、无尿、急性肾功能不全者禁用。', '与ACEI/ARB或补钾剂联用需严密监测血钾。', 0, 72),
('阿托伐他汀钙片', '立普妥', 'Atorvastatin Calcium Tablets', '他汀类调脂药', '心血管内科,内分泌科', '片剂 20mg×7片', '高胆固醇血症与混合型高脂血症；冠心病及高危人群调脂稳定斑块。', '口服，一日1次，一次10～20mg（可调至40～80mg），晚间或任意固定时间服用。', '肌痛、转氨酶升高、消化不良；罕见横纹肌溶解。', '活动性肝病或转氨酶持续显著升高者、妊娠及哺乳期禁用。', '用药期间监测肝功能与肌酶；出现不明原因肌痛需排查；避免与强效CYP3A4抑制剂同服。', 0, 88),
('瑞舒伐他汀钙片', '可定', 'Rosuvastatin Calcium Tablets', '他汀类调脂药', '心血管内科,内分泌科', '片剂 10mg×7片', '高胆固醇血症、混合型血脂异常；动脉粥样硬化性心血管病防治。', '口服，一日1次，一次10mg（可5～20mg调整）。', '肌痛、便秘、恶心、转氨酶升高。', '活动性肝病、严重肾功能不全、妊娠哺乳期禁用。', '亚洲人群对10mg以上剂量敏感性高；用药期间监测肝功能、肌酶。', 0, 87),
('非诺贝特胶囊', '力平之', 'Fenofibrate Capsules', '贝特类调脂药', '心血管内科,内分泌科', '胶囊 200mg×10粒', '高甘油三酯血症、混合型高脂血症（甘油三酯显著升高为主时）。', '口服，一日1次，一次200mg，与餐同服。', '胃肠道不适、转氨酶升高、肌痛；胆结石风险增加。', '严重肝肾功能不全、胆囊疾病、妊娠哺乳期禁用。', '与他汀类联用增加肌病风险需谨慎；用药期间监测肝功能。', 0, 82),
('硝酸甘油片', NULL, 'Nitroglycerin Tablets', '硝酸酯类', '心血管内科,急诊科', '片剂 0.5mg×100片', '心绞痛急性发作的缓解与预防。', '舌下含服，一次0.5mg，若5分钟未缓解可再含服一片，最多3片；不可吞服。', '头痛、面部潮红、低血压、心动过速；连续用易耐药。', '严重低血压、肥厚型梗阻性心肌病、颅内压增高、使用PDE5抑制剂（西地那非等）者禁用。', '含服时取坐位防跌倒；药物需避光密闭保存并注意效期；长期使用需留无药间期防耐药。', 0, 95),
('单硝酸异山梨酯缓释片', '依姆多', 'Isosorbide Mononitrate Sustained-release Tablets', '硝酸酯类', '心血管内科', '缓释片 60mg×7片', '冠心病心绞痛的长期预防、慢性心力衰竭的辅助治疗。', '口服，一日1次，一次30～60mg，晨服整片吞服。', '头痛（治疗初期常见）、低血压、面部潮红。', '急性循环衰竭、严重低血压、肥厚型梗阻性心肌病者禁用。', '应设置每日无药间期（如晨服）减少耐药；与降压药联用注意低血压。', 0, 70),
('地高辛片', NULL, 'Digoxin Tablets', '强心苷类', '心血管内科', '片剂 0.25mg×30片', '慢性心力衰竭（尤其合并房颤）、心房颤动的心室率控制。', '口服，一日1次，一次0.125～0.25mg，剂量个体化（需监测血药浓度）。', '恶心呕吐、心律失常（室早、房室传导阻滞）、黄视绿视等中毒表现。', '室颤、肥厚型梗阻性心肌病、预激综合征伴房颤者禁用。', '治疗窗窄，需监测血药浓度与电解质（低钾增加中毒）；与胺碘酮、奎尼丁等合用需减量。', 0, 74),
('盐酸胺碘酮片', NULL, 'Amiodarone Hydrochloride Tablets', 'Ⅲ类抗心律失常药', '心血管内科', '片剂 0.2g×24片', '室性及室上性心律失常（房颤复律与维持窦律、危及生命的室速/室颤预防）。', '口服，负荷量后维持一日0.2g或更低，具体遵医嘱。', '甲状腺功能异常、肺间质纤维化、肝酶升高、角膜微沉着、光敏。', '严重窦房结功能不全、二/三度房室传导阻滞、碘过敏、甲状腺功能异常者禁用。', '长期使用需定期监测甲状腺功能、肝功能、胸片与心电图；注意与其他延长QT药物相互作用。', 0, 76),
('曲美他嗪片', '万爽力', 'Trimetazidine Tablets', '抗心绞痛药（代谢调节）', '心血管内科', '片剂 20mg×30片', '心绞痛发作的预防性治疗；眩晕与耳鸣的辅助治疗。', '口服，一日2～3次，一次20mg，餐时服用。', '恶心、头晕、乏力；帕金森样症状（罕见）。', '帕金森病、震颤及其他锥体外系症状者禁用。', '不作为心绞痛急性发作的一线用药；出现运动障碍症状应停药。', 0, 60);
INSERT INTO drug (generic_name, trade_name, english_name, category, department, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, is_otc, sort) VALUES
('硫酸沙丁胺醇气雾剂', '万托林', 'Salbutamol Sulfate Aerosol', 'β2受体激动剂（短效SABA）', '呼吸内科,急诊科', '气雾剂 100μg/揿×200揿', '支气管哮喘急性发作、慢阻肺急性加重时的快速缓解。', '吸入，必要时1～2揿；24小时不超过8揿（具体遵医嘱）。', '手抖、心悸、心动过速、低钾（大剂量）。', '对本品过敏者禁用。', '不能替代长效控制药物；每周需用超过2次提示控制不佳，应就医升级方案。', 0, 90),
('布地奈德福莫特罗粉吸入剂', '信必可都保', 'Budesonide/Formoterol Fumarate Powder for Inhalation', '吸入糖皮质激素+长效β2激动剂（ICS/LABA）', '呼吸内科', '粉吸入剂 160/4.5μg×60吸', '哮喘的长期控制治疗（需ICS+LABA联用者）、慢阻肺维持治疗。', '吸入，一日1～2次，一次1～2吸，用后漱口。', '口咽部念珠菌感染、声音嘶哑、心悸；长期大剂量全身影响少见。', '对本品任一成分过敏者禁用。', '不能用于急性发作缓解；吸药后务必漱口减少口咽念珠菌感染。', 0, 92),
('噻托溴铵粉吸入剂', '思力华', 'Tiotropium Bromide Powder for Inhalation', '长效抗胆碱能药（LAMA）', '呼吸内科', '粉吸入剂 18μg×30粒', '慢阻肺的长期维持治疗，减少急性加重；哮喘的附加治疗。', '吸入，一日1次，一次1粒。', '口干、咳嗽、咽部刺激；少见尿潴留、青光眼加重。', '对阿托品/本品过敏者禁用；闭角型青光眼、前列腺增生伴尿潴留者慎用。', '胶囊仅供吸入装置使用，不可吞服；勿使粉末入眼。', 0, 86),
('孟鲁司特钠片', '顺尔宁', 'Montelukast Sodium Tablets', '白三烯受体拮抗剂', '呼吸内科', '咀嚼片/片剂 10mg×5片', '哮喘的预防和长期治疗（尤其运动诱发性支气管收缩、阿司匹林敏感哮喘）；过敏性鼻炎。', '口服，一日1次，一次10mg，睡前服用。', '头痛、腹痛、口苦；罕见神经精神事件（失眠、激越、抑郁）。', '对本品过敏者禁用。', '不用于哮喘急性发作；出现行为情绪异常应评估停药并告知医师。', 0, 82),
('盐酸氨溴索片', '沐舒坦', 'Ambroxol Hydrochloride Tablets', '祛痰药', '呼吸内科', '片剂 30mg×20片', '急慢性支气管炎、肺炎、慢阻肺等伴痰液粘稠不易咳出者。', '口服，一日3次，一次30mg；餐后服用。', '胃部不适、恶心、皮疹（少见）。', '对本品过敏者禁用；妊娠早期慎用。', '仅祛痰对症，需配合病因治疗；溃疡病患者慎用。', 1, 88),
('乙酰半胱氨酸泡腾片', '富露施', 'Acetylcysteine Effervescent Tablets', '粘液溶解剂/抗氧化剂', '呼吸内科', '泡腾片 600mg×10片', '浓稠痰液过多的呼吸系统疾病（慢支、肺气肿、肺炎后）的祛痰。', '口服，一日1次，一次600mg，溶于半杯温水后服用。', '恶心、呕吐、皮疹；罕见支气管痉挛。', '哮喘急性发作期、对乙酰半胱氨酸过敏者禁用。', '泡腾片不可直接吞服；哮喘患者慎用；与止咳药联用需防痰液堵塞气道。', 0, 78),
