('甲巯咪唑片', '赛治', 'Thiamazole Tablets', '抗甲状腺药（硫脲类）', '内分泌科', '片剂 10mg×50片', '甲亢的内科治疗、甲亢术前准备及放射性碘治疗前准备。', '口服，起始一日10～30mg，分次或顿服，维持量遵医嘱。', '皮疹、瘙痒、粒细胞缺乏（可致命，需警惕咽痛发热）、肝功能异常。', '对本品过敏、严重粒细胞缺乏史者禁用；妊娠早期慎用。', '用药期间定期复查血常规与肝功能；出现咽痛、发热立即停药查血象。', 0, 82),
('醋酸泼尼松片', NULL, 'Prednisone Acetate Tablets', '糖皮质激素', '内分泌科,风湿免疫科,呼吸内科', '片剂 5mg×100片', '多种炎症性、自身免疫性疾病（哮喘、类风湿关节炎、肾病综合征、溃疡性结肠炎等）。', '口服，剂量因疾病而异，晨起顿服为佳，需逐渐减量停药。', '向心性肥胖、血糖血压升高、骨质疏松、消化道溃疡、感染风险增加、精神症状。', '严重精神病史、活动性消化道溃疡、未控制的严重感染、单纯疱疹角膜炎者禁用（抢救除外）。', '不可骤停以免肾上腺皮质功能不全；长期使用需补钙与维生素D并监测血糖血压；接种活疫苗需谨慎。', 0, 90),
('碳酸钙D3片', '钙尔奇D', 'Calcium Carbonate and Vitamin D3 Tablets', '钙与维生素D补充剂', '内分泌科,全科', '片剂 600mg/400IU×30片', '钙与维生素D缺乏的防治（骨质疏松、骨软化、孕期哺乳期、老年人补钙）。', '口服，一日1～2片，餐中或餐后服用。', '便秘、腹胀、嗳气；过量可致高钙血症。', '高钙血症、高钙尿症、肾结石患者禁用。', '与含铁、四环素、喹诺酮类药物间隔2小时以上；尿路结石者慎用。', 1, 66),
('阿仑膦酸钠片', '福善美', 'Alendronate Sodium Tablets', '双膦酸盐类（抗骨质疏松）', '内分泌科', '片剂 70mg×4片', '绝经后骨质疏松、男性骨质疏松及糖皮质激素性骨质疏松的治疗。', '口服，一周1次，一次70mg，晨起空腹以足量白水送服，服后保持直立30分钟。', '上消化道刺激（反流性食管炎、食管溃疡）、骨肌痛、低钙血症相关反应。', '食管排空延迟（食管狭窄、贲门失弛缓）、不能站立或端坐30分钟者、严重肾功能不全者禁用。', '服药后勿平躺勿进食以免食管损伤；用药前纠正低钙与维生素D缺乏。', 0, 60);
INSERT INTO drug (generic_name, trade_name, english_name, category, department, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, is_otc, sort) VALUES
('甲钴胺片', '弥可保', 'Mecobalamin Tablets', '营养神经药（维生素B12类）', '神经内科', '片剂 0.5mg×20片', '周围神经病变（糖尿病性、酒精性、药物性及颈椎腰椎病变相关）。', '口服，一日3次，一次0.5mg。', '食欲不振、恶心、皮疹（偶见）。', '对本品过敏者禁用。', '连续用药1个月以上无效者应就医评估病因。', 0, 80),
('加巴喷丁胶囊', NULL, 'Gabapentin Capsules', '抗癫痫/神经病理性疼痛药', '神经内科', '胶囊 0.1g×50粒', '带状疱疹后神经痛等神经病理性疼痛；成人癫痫部分性发作的辅助治疗。', '口服，需从低剂量滴定（首日0.3g起分次），目标剂量遵医嘱。', '头晕、嗜睡、共济失调、外周水肿。', '对本品过敏者禁用；急性胰腺炎者禁用。', '突然停药可致戒断反应，须逐步减量；驾驶等需注意力活动慎用。', 0, 76),
('盐酸普瑞巴林胶囊', '乐瑞卡', 'Pregabalin Hydrochloride Capsules', '抗惊厥/神经病理性疼痛药', '神经内科', '胶囊 75mg×8粒', '带状疱疹后神经痛、纤维肌痛、糖尿病周围神经痛；广泛性焦虑障碍辅助。', '口服，一日2次，一次75～150mg，按疗效耐受调整。', '头晕、嗜睡、口干、水肿、视物模糊。', '对本品过敏者禁用。', '逐步减量停药防戒断；与中枢抑制剂合用增强镇静；驾驶慎用。', 0, 74),
('盐酸多奈哌齐片', '安理申', 'Donepezil Hydrochloride Tablets', '胆碱酯酶抑制剂（阿尔茨海默病）', '神经内科', '片剂 5mg×7片', '轻中度阿尔茨海默型痴呆的症状治疗。', '口服，一日1次，一次5mg，睡前服用，1个月后可遵医嘱增至10mg。', '恶心、腹泻、失眠、肌肉痉挛、心动过缓。', '对本品过敏者禁用。', '病窦综合征、消化道溃疡、哮喘者慎用；监测心率与胃肠道症状。', 0, 70),
('左乙拉西坦片', '开浦兰', 'Levetiracetam Tablets', '抗癫痫药', '神经内科', '片剂 0.25g×30片', '成人及儿童癫痫部分性发作、肌阵挛发作、全面强直阵挛发作的添加治疗。', '口服，起始一日2次，一次0.25g，逐步加量（遵医嘱）。', '嗜睡、乏力、头晕、易激惹；罕见严重皮肤反应。', '对吡咯烷酮衍生物过敏者禁用。', '不可突然停药；肾功能不全者需调整剂量；出现皮疹或精神症状及时就医。', 0, 68),
('丙戊酸钠缓释片', '德巴金', 'Sodium Valproate Sustained-release Tablets', '广谱抗癫痫药/心境稳定剂', '神经内科', '缓释片 0.5g×30片', '全面性及部分性癫痫发作；双相情感障碍躁狂发作。', '口服，一日1～2次，起始一日0.5g，个体化滴定。', '恶心、震颤、脱发、体重增加、肝功能损害、血小板减少。', '急性或慢性肝炎、严重肝功能不全、线粒体病、妊娠期（致畸）禁用或极谨慎。', '用药前及期间定期监测肝功能、血常规、血药浓度；育龄女性需评估并避孕咨询。', 0, 66),
('卡马西平片', NULL, 'Carbamazepine Tablets', '抗癫痫药/三叉神经痛药', '神经内科', '片剂 0.1g×100片', '癫痫部分性发作及全面强直阵挛发作、三叉神经痛、舌咽神经痛。', '口服，一日2～3次，起始一次0.1g，逐步加量。', '头晕、复视、恶心、低钠血症、皮疹；严重皮肤反应（SJS/TEN）与再生障碍性贫血罕见。', '房室传导阻滞、有骨髓抑制史、与单胺氧化酶抑制剂同用者禁用。', '需监测血常规、肝功能、电解质；出现皮疹（尤其伴发热）立即停药就医；诱导肝酶影响多种合用药。', 0, 64),
('盐酸舍曲林片', '左洛复', 'Sertraline Hydrochloride Tablets', '选择性5-羟色胺再摄取抑制剂（SSRI）', '神经内科,全科', '片剂 50mg×14片', '抑郁症、强迫症、惊恐障碍、社交焦虑障碍、创伤后应激障碍。', '口服，一日1次，一次50mg，可增至100～200mg（遵医嘱）。', '恶心、腹泻、失眠或嗜睡、性功能障碍、头痛。', '与单胺氧化酶抑制剂（MAOI）合用或停用MAOI不足14天者禁用。', '青少年及年轻成人用药需监测自杀观念与激越；起效需1～2周，停药需逐渐减量。', 0, 62),
('盐酸艾司唑仑片', NULL, 'Estazolam Hydrochloride Tablets', '苯二氮䓬类（镇静催眠）', '神经内科,全科', '片剂 1mg×20片', '失眠症的短期治疗、焦虑、紧张恐惧及术前镇静。', '口服，一次1～2mg，睡前服用，短期使用。', '日间困倦、头晕、共济失调、记忆力下降；长期使用耐受与依赖。', '重症肌无力、严重呼吸功能不全、睡眠呼吸暂停综合征者禁用。', '仅短期使用避免依赖；与酒精及中枢抑制剂合用显著增强抑制；老年人减量；避免突然停药。', 0, 72),
('马来酸咪达唑仑片', NULL, 'Midazolam Maleate Tablets', '苯二氮䓬类', '神经内科,急诊科', '片剂 15mg×10片', '各种失眠及睡眠节律障碍的短期治疗。', '口服，一次7.5～15mg，睡前服用。', '嗜睡、遗忘、运动失调；呼吸抑制（大剂量）。', '重症肌无力、严重呼吸功能不全、急性酒精中毒者禁用。', '严格短期使用；驾车操作机器当日避免使用；老年及肝肾功能减退者减量。', 0, 58);
INSERT INTO drug (generic_name, trade_name, english_name, category, department, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, is_otc, sort) VALUES
('阿莫西林胶囊', NULL, 'Amoxicillin Capsules', '青霉素类抗生素', '呼吸内科,感染科,全科', '胶囊 0.25g×24粒', '敏感菌所致呼吸道、泌尿道、皮肤软组织、中耳炎、鼻窦炎等感染。', '口服，一日3～4次，一次0.5g，餐后服用（遵医嘱）。', '皮疹、恶心腹泻；过敏性休克罕见但严重。', '青霉素过敏者禁用。', '用药前必须做青霉素皮试（按机构规范）；传染性单核细胞增多症患者易发皮疹应避免使用。', 0, 94),
