('左氧氟沙星片', '可乐必妥', 'Levofloxacin Tablets', '氟喹诺酮类抗生素', '呼吸内科,感染科,泌尿内科', '片剂 0.5g×7片', '社区获得性肺炎、慢性支气管炎急性发作、泌尿道感染、皮肤软组织感染等敏感菌感染。', '口服，一日1次，一次0.5g（剂量疗程遵医嘱）。', '胃肠道反应、头晕失眠、光敏、肌腱炎；QT延长；血糖波动。', '对喹诺酮类过敏者、18岁以下青少年（骨骼发育）、妊娠哺乳期禁用。', '避免与含金属抗酸剂同服（间隔2小时）；出现肌腱疼痛或神经系统症状停药；老年及肾功能减退者调整剂量。', 0, 90),
('盐酸莫西沙星片', '拜复乐', 'Moxifloxacin Hydrochloride Tablets', '氟喹诺酮类抗生素', '呼吸内科,感染科', '片剂 0.4g×3片', '社区获得性肺炎、慢性支气管炎急性加重、急性鼻窦炎等敏感菌感染。', '口服，一日1次，一次0.4g。', '恶心、腹泻、头晕、QT间期延长、肝酶升高。', '对喹诺酮过敏者、QT延长或低钾者、妊娠哺乳期、18岁以下禁用。', '避免与延长QT药物合用；监测肝功能；肌腱损伤风险同其他喹诺酮。', 0, 86),
('阿奇霉素片', '希舒美', 'Azithromycin Tablets', '大环内酯类抗生素', '呼吸内科,感染科,全科', '片剂 0.25g×6片', '敏感菌所致咽炎扁桃体炎、中耳炎、鼻窦炎、社区获得性肺炎、支原体衣原体感染。', '口服，一日1次，一次0.5g，连用3日或首日0.5g后一日0.25g连用4日。', '腹痛、腹泻、恶心；QT延长与肝损伤（罕见）。', '对大环内酯类过敏者禁用。', '肝功能不全者慎用；合并心血管疾病者注意QT；与含铝镁抗酸剂间隔服用。', 0, 92),
('克拉霉素片', NULL, 'Clarithromycin Tablets', '大环内酯类抗生素', '呼吸内科,消化内科,感染科', '片剂 0.25g×8片', '敏感菌所致呼吸道、皮肤软组织感染；与PPI等联用根除幽门螺杆菌。', '口服，一日2次，一次0.25～0.5g（根除Hp方案遵医嘱）。', '腹痛、腹泻、味觉异常、肝酶升高。', '对大环内酯类过敏者禁用；与特非那定、西沙必利等合用致QT延长者禁用。', '是强效CYP3A4抑制剂，与他汀类、苯二氮䓬类等合用时需调整并监测。', 0, 88),
('盐酸多西环素片', NULL, 'Doxycycline Hyclate Tablets', '四环素类抗生素', '呼吸内科,感染科,皮肤科', '片剂 0.1g×20片', '支原体/衣原体感染、立克次体病、痤疮、布鲁菌病等；疟疾预防。', '口服，一日1～2次，一次0.1g，餐后多饮水服用。', '胃肠道刺激、光敏、食管溃疡；牙齿变色（儿童）。', '8岁以下儿童、妊娠哺乳期禁用。', '服药时保持直立并用足量水；避免暴晒；与含钙铁镁制剂间隔服用。', 0, 78),
('甲硝唑片', NULL, 'Metronidazole Tablets', '硝基咪唑类抗生素', '消化内科,感染科,妇科', '片剂 0.2g×100片', '厌氧菌感染、滴虫病、阿米巴病；与抗菌药联用根除幽门螺杆菌。', '口服，一日3次，一次0.2～0.4g（方案遵医嘱）。', '恶心、金属味、头痛、尿色加深；周围神经病变（长疗程）。', '对硝基咪唑类过敏者、妊娠早期禁用。', '服药及停药后3日内禁酒（双硫仑样反应）；中枢神经系统疾病者慎用。', 0, 82),
('复方磺胺甲噁唑片', '复方新诺明', 'Sulfamethoxazole and Trimethoprim Tablets', '磺胺类抗生素', '呼吸内科,感染科,肾内科', '片剂 0.48g×100片', '敏感菌所致泌尿道感染、卡氏肺孢子虫肺炎（治疗与预防）、诺卡菌病等。', '口服，一日2次，一次2片（剂量遵医嘱），多饮水。', '皮疹、恶心、光敏、结晶尿、骨髓抑制；SJS等严重皮肤反应。', '对磺胺类过敏者、严重肝肾功能不全者、妊娠晚期及2月龄以下婴儿禁用。', '服药期间大量饮水防结晶尿；定期查血常规；肾功能减退者调整剂量。', 0, 70),
('氟康唑胶囊', '大扶康', 'Fluconazole Capsules', '三唑类抗真菌药', '呼吸内科,感染科', '胶囊 0.15g×1粒', '念珠菌病（口腔、食管、系统性）、隐球菌脑膜炎；真菌感染的预防。', '口服，首剂0.4g，后一日0.2g（剂量遵医嘱）。', '恶心、腹痛、肝酶升高、皮疹；QT延长（大剂量）。', '对唑类过敏者禁用；与特非那定、西沙必利等合用。', '监测肝功能；与华法林、磺脲类、他汀类等合用时相互作用多需调整。', 0, 68),
('磷酸奥司他韦胶囊', '达菲', 'Oseltamivir Phosphate Capsules', '神经氨酸酶抑制剂（抗流感）', '呼吸内科,急诊科', '胶囊 75mg×10粒', '成人和1岁以上儿童甲型/乙型流感的治疗；流感暴露后的预防。', '口服，一日2次，一次75mg，连用5日；预防一日1次。', '恶心、呕吐（餐中服可减轻）、头痛；罕见神经精神事件。', '对本品过敏者禁用。', '发病48小时内启用效果最佳；虽可缩短病程，仍需对症支持与隔离。', 0, 84),
('阿昔洛韦片', NULL, 'Aciclovir Tablets', '核苷类抗病毒药（抗疱疹）', '感染科,全科,皮肤科', '片剂 0.2g×25片', '单纯疱疹、带状疱疹病毒感染的治疗与预防。', '口服，一日5次，一次0.2g（带状疱疹遵医嘱0.8g每日5次）。', '恶心、腹泻、头痛、皮疹；肾功能不全（大剂量静脉）。', '对本品过敏者禁用。', '肾病患者减量；服药多饮水减少结晶尿；疗程不足易复发。', 0, 76),
('异烟肼片', NULL, 'Isoniazid Tablets', '抗结核药', '呼吸内科,感染科', '片剂 0.1g×100片', '各型肺结核及肺外结核的联合化疗（一线药物）。', '口服，一日1次，一次0.3g（按体重，晨顿服）。', '周围神经炎（合用维生素B6预防）、肝损害、皮疹。', '对异烟肼过敏、急性肝病者禁用。', '用药前及期间定期查肝功能；与利福平台用注意肝毒性叠加；嗜酒者风险更高。', 0, 80),
('利福平胶囊', NULL, 'Rifampicin Capsules', '抗结核药（利福霉素类）', '呼吸内科,感染科', '胶囊 0.15g×100粒', '结核病联合化疗；麻风病；脑膜炎奈瑟菌带菌者治疗。', '口服，一日1次，晨起空腹顿服0.45～0.6g（遵医嘱）。', '肝功能异常、胃肠道反应、尿泪汗液呈橘红色（正常现象）；皮疹。', '严重肝功能不全、胆道梗阻者禁用。', '强效肝酶诱导剂，显著影响口服避孕药、华法林、他汀等多种药物；监测肝功能。', 0, 79),
('盐酸乙胺丁醇片', NULL, 'Ethambutol Hydrochloride Tablets', '抗结核药', '呼吸内科,感染科', '片剂 0.25g×100片', '与其他抗结核药联合治疗各型结核病。', '口服，一日1次，按体重15～25mg/kg（遵医嘱）。', '视神经炎（视力下降、色觉异常）、胃肠道反应、高尿酸。', '对本品过敏者禁用；糖尿病视网膜病变者慎用。', '用药期间定期检查视力和色觉；肾功能不全者调整剂量。', 0, 72);
INSERT INTO drug (generic_name, trade_name, english_name, category, department, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, is_otc, sort) VALUES
('硫酸亚铁缓释片', NULL, 'Ferrous Sulfate Sustained-release Tablets', '抗贫血药（铁剂）', '血液内科,全科', '缓释片 0.45g×30片', '缺铁性贫血的治疗与预防。', '口服，一日1～2次，一次1片，餐后服用。', '胃肠道刺激（恶心、便秘、黑便）。', '非缺铁性贫血（如地中海贫血、铁粒幼细胞贫血）、血色病者禁用。', '与牛奶、茶、咖啡及抗酸剂同服影响吸收，宜间隔服用；大便变黑属正常。', 0, 78),
('叶酸片', NULL, 'Folic Acid Tablets', '抗贫血药（叶酸）', '血液内科,全科', '片剂 5mg×100片', '巨幼细胞性贫血（叶酸缺乏所致）；妊娠期预防胎儿神经管畸形。', '口服，治疗一日1～3次，一次5mg；围孕期预防一日0.4～0.8mg。', '偶见胃肠道反应。', '对叶酸过敏者禁用。', '维生素B12缺乏所致恶性贫血者单用叶酸可掩盖神经症状，需先鉴别。', 1, 74),
('重组人促红素注射液', '益比奥', 'Recombinant Human Erythropoietin Injection', '造血生长因子', '血液内科,肾内科', '注射液 3000IU×1支', '肾性贫血、肿瘤化疗相关性贫血等。', '皮下或静脉注射，剂量个体化（按Hb水平调整）。', '血压升高、头痛、血栓事件风险；注射部位反应。', '未控制的重度高血压患者禁用。', '用药期间监测血压与血红蛋白（避免Hb过快升高）；纯红细胞再生障碍罕见。', 0, 66),
('秋水仙碱片', NULL, 'Colchicine Tablets', '抗痛风药', '风湿免疫科,全科', '片剂 0.5mg×50片', '痛风急性发作的治疗与预防。', '口服，急性期首剂1.0mg，1小时后0.5mg，12小时后按预防剂量（方案遵医嘱）。', '恶心、呕吐、腹泻（早期毒性信号）；骨髓抑制与肌神经病变（过量/肾功能不全）。', '严重肝肾功能不全、骨髓抑制者禁用。', '治疗窗窄，腹泻即提示中毒应停药；与CYP3A4抑制剂（克拉霉素、唑类）及他汀合用需减量。', 0, 80),
('别嘌醇片', NULL, 'Allopurinol Tablets', '抑制尿酸生成药', '风湿免疫科,肾内科', '片剂 0.1g×100片', '痛风（高尿酸血症）的长期降尿酸治疗；尿酸性肾结石。', '口服，起始一日1次，一次0.1g，逐步加量（遵医嘱），餐后服。', '皮疹（严重SJS/TEN可致命，须警惕）、胃肠道反应、肝功异常。', '对本品过敏者禁用；急性痛风发作期不宜新启。', '从小剂量起始并在急性发作控制后启用；出现皮疹立即停药；与硫唑嘌呤合用需大幅减量。', 0, 78),
('非布司他片', '优立通', 'Febuxostat Tablets', '抑制尿酸生成药', '风湿免疫科,内分泌科', '片剂 40mg×14片', '痛风患者高尿酸血症的长期治疗（对别嘌醇不耐受者尤其适用）。', '口服，一日1次，一次40mg，2周后可按需增至80mg。', '肝功能异常、恶心、关节痛；心血管血栓事件风险需关注。', '对本品过敏者禁用。', '启动初期痛风发作风险升高，可预防性合用抗炎药；定期监测肝功能与心血管情况。', 0, 76),
('布洛芬缓释胶囊', '芬必得', 'Ibuprofen Sustained-release Capsules', '非甾体抗炎药（NSAIDs）', '全科,风湿免疫科,急诊科', '缓释胶囊 0.3g×20粒', '关节痛、肌肉痛、头痛、牙痛、痛经等轻中度疼痛及发热、骨关节炎等炎症性疼痛。', '口服，一日2次，一次0.3g，餐后服用。', '胃肠道不适、恶心；长期大剂量可致溃疡出血、肾功能影响。', '活动性消化道溃疡出血者、严重心衰、妊娠晚期、对NSAIDs过敏者禁用。', '不宜长期服用；与阿司匹林、华法林、糖皮质激素合用增加出血风险；肾功能不全者慎用。', 1, 84),
('双氯芬酸钠缓释片', '扶他林', 'Diclofenac Sodium Sustained-release Tablets', '非甾体抗炎药（NSAIDs）', '全科,风湿免疫科', '缓释片 75mg×10片', '类风湿关节炎、骨关节炎、强直性脊柱炎及急性软组织损伤疼痛。', '口服，一日1次，一次75mg，餐后整片吞服。', '胃肠道反应、头痛头晕、肝酶升高；心血管血栓风险。', '活动性消化道溃疡出血、严重心衰、冠脉搭桥围术期者禁用。', '老年及肾功能不全者用最低有效剂量短疗程；避免与其他NSAIDs合用。', 0, 82),
('塞来昔布胶囊', '西乐葆', 'Celecoxib Capsules', '选择性COX-2抑制剂（NSAIDs）', '风湿免疫科,全科', '胶囊 0.2g×6粒', '骨关节炎、类风湿关节炎、强直性脊柱炎及急性疼痛的症状缓解。', '口服，一日1～2次，一次0.1～0.2g，餐后服用。', '消化不良、腹痛、水肿；心血管血栓风险较传统NSAIDs略升（长期大剂量）。', '对磺胺类过敏者、活动性消化道溃疡出血者、严重心衰者禁用。', '胃肠道出血风险低于传统NSAIDs但仍有；监测血压肾功能；与华法林合用监测INR。', 0, 80),
('甲氨蝶呤片', NULL, 'Methotrexate Tablets', '抗风湿药（叶酸拮抗剂/免疫抑制剂）', '风湿免疫科,血液内科', '片剂 2.5mg×16片', '类风湿关节炎、银屑病关节炎的活动期治疗；多种肿瘤的化疗。', '口服，一周1次（每周固定日），一次7.5～15mg；严禁每日服用。', '恶心、口腔溃疡、骨髓抑制、肝肺毒性；每周给药错误可致死。', '妊娠哺乳期、严重肝肾功能不全、明显骨髓抑制者禁用。', '每周1次用药是安全关键，须反复核对；常规联合叶酸；定期监测血常规、肝肾功能。', 0, 86),
('硫酸羟氯喹片', '赛能', 'Hydroxychloroquine Sulfate Tablets', '抗疟药/抗风湿药（DMARD）', '风湿免疫科', '片剂 0.1g×14片', '类风湿关节炎、系统性红斑狼疮的疾病活动控制。', '口服，一日1～2次，一次0.1～0.2g（按体重），餐中服。', '胃肠道反应、皮疹、视网膜病变（长期累积）、肌无力。', '对4-氨基喹啉类过敏者、已有视网膜病变者禁用。', '累积剂量相关视网膜毒性，用药超过5年或累积量大需定期眼科筛查；肾功能不全减量。', 0, 72);
INSERT INTO drug (generic_name, trade_name, english_name, category, department, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, is_otc, sort) VALUES
('对乙酰氨基酚片', '泰诺林', 'Paracetamol Tablets', '解热镇痛药', '全科,急诊科', '片剂 0.5g×10片', '感冒发热、头痛、关节痛、牙痛等轻中度疼痛。', '口服，一次0.5g，一日不超过2g（最大4次），间隔4～6小时。', '偶见皮疹；过量可致严重肝损伤。', '严重肝功能不全者禁用。', '多种复方感冒药含本品，重复用药易超量；避免饮酒；连续退热不超过3日。', 1, 88),
('盐酸小檗碱片', NULL, 'Berberine Hydrochloride Tablets', '肠道抗感染药', '全科,消化内科', '片剂 0.1g×100片', '肠道感染引起的腹泻、肠炎。', '口服，一日3次，一次0.1～0.3g。', '偶见恶心、便秘；过量可致中毒。', '对本品过敏者禁用；葡萄糖-6-磷酸脱氢酶缺乏者（溶血）禁用。', '腹泻伴高热脓血便时应就医明确病因；注意补液。', 1, 66),
('口服补液盐Ⅲ', NULL, 'Oral Rehydration Salts Ⅲ', '电解质补充剂', '全科,急诊科,消化内科', '散剂 5.125g×6袋', '轻中度腹泻、呕吐所致脱水与电解质紊乱的补充。', '口服，一袋溶于250ml温凉水，按需少量多次服用（腹泻量1:1补）。', '一般无明显不良反应；冲调不当可致高钠。', '严重脱水休克需静脉补液者不能替代。', '必须按说明水量冲调，不可加糖调味；分次服完，凉后不可再煮沸。', 1, 70),
('马来酸氯苯那敏片', '扑尔敏', 'Chlorphenamine Maleate Tablets', '第一代抗组胺药', '全科,呼吸内科', '片剂 4mg×100片', '过敏性鼻炎、荨麻疹、皮肤瘙痒等过敏性疾病。', '口服，一日3次，一次4mg。', '明显嗜睡、口干、头晕；老年人排尿困难。', '对本品过敏者、青光眼、前列腺增生伴排尿困难者禁用。', '服药期间勿驾车或操作机械；勿与酒精及镇静药同用。', 1, 72),
('复方甘草片', NULL, 'Compound Licorice Tablets', '镇咳祛痰药（含阿片粉）', '全科,呼吸内科', '片剂 复方×100片', '镇咳祛痰，用于剧烈咳嗽的对症治疗。', '口服或含服，一次3～4片，一日3次。', '恶心、便秘、嗜睡；长期滥用可成瘾。', '对成分过敏者、孕妇（阿片成分）禁用。', '含阿片粉具成瘾性，不宜长期连续使用；驾驶前慎用。', 0, 74),
('维生素B1片', NULL, 'Vitamin B1 Tablets', '维生素类', '全科,神经内科', '片剂 10mg×100片', '维生素B1缺乏症（脚气病）及周围神经炎、消化不良的辅助治疗。', '口服，一日3次，一次10～30mg。', '偶见过敏反应。', '对本品过敏者禁用。', '长期大量使用需遵医嘱；与其他B族维生素协同补充。', 1, 62),
('维生素C片', NULL, 'Vitamin C Tablets', '维生素类', '全科', '片剂 0.1g×100片', '坏血病的防治；机体氧化应激及感染、创伤时的辅助补充。', '口服，一日1～3次，一次0.1g。', '大剂量可致腹泻、结石（草酸盐）、停药反跳。', '对本品过敏者禁用；肾功能不全、草酸钙结石者慎用。', '不宜长期超大剂量服用；与铁剂同服可促进铁吸收。', 1, 60),
('盐酸地芬尼多片', NULL, 'Difenidol Hydrochloride Tablets', '抗眩晕药', '全科,神经内科,耳鼻喉科', '片剂 25mg×30片', '防治多种原因（内耳眩晕、晕车晕船、术后）引起的眩晕与恶心呕吐。', '口服，一次25～50mg，一日3次，乘车前30分钟服用。', '口干、嗜睡、视物模糊；心动过缓、低血压（大剂量）。', '对本品过敏者、严重肾功能不全者禁用。', '青光眼、前列腺肥大者慎用；用药后避免驾驶。', 1, 64),
('苯磺酸左氨氯地平片', '安内真', 'Levamlodipine Besylate Tablets', '钙通道阻滞剂（CCB）', '心血管内科', '片剂 2.5mg×14片', '高血压、慢性稳定性心绞痛。', '口服，一日1次，一次2.5～5mg。', '踝部水肿、面部潮红、头痛。', '对二氢吡啶类过敏者禁用；严重低血压者慎用。', '肝功能不全者减量；长期用后停药应逐步减量。', 0, 62);
INSERT INTO drug (generic_name, trade_name, english_name, category, department, dosage_form, indications, usage_dosage, adverse_reactions, contraindications, precautions, is_otc, sort) VALUES
